// Live RPC data
async function rpc(method, params=[]) {
  const resp = await fetch('/rpc', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({jsonrpc: '2.0', method, params, id: 1})
  });
  const data = await resp.json();
  return data.result;
}

async function loadValidators() {
  try {
    // Fetch chain header
    const header = await rpc('chain_getHeader');
    const blockNum = parseInt(header.number, 16);
    document.getElementById('statBlock').textContent = '#' + blockNum;

    // Fetch health
    const health = await rpc('system_health');
    document.getElementById('statPeers').textContent = health.peers;

    // Fetch active validators
    let validators = [];
    try {
      validators = await rpc('dpos_activeValidators');
    } catch(e) {
      // Fallback: try dpos_allValidators
      try { validators = await rpc('dpos_allValidators'); } catch(e2) {}
    }

    if (!Array.isArray(validators)) validators = validators ? [validators] : [];

    document.getElementById('statValidators').textContent = validators.length;
    document.getElementById('valCount').textContent = validators.length + ' validators active';

    // Render validator rows
    const colors = ['#caff33', '#4ade80', '#fbbf24', '#60a5fa', '#f472b6', '#a78bfa', '#fb923c', '#34d399'];
    const names = ['Alice', 'Bob', 'Charlie', 'Dave', 'Eve', 'Ferdie', 'GreenNode', 'EcoValidator', 'VerdisRanger', 'CarbonNode', 'ForestGuard', 'SolarStake', 'WindValidator', 'HydroNode'];

    let html = '';
    validators.forEach((val, i) => {
      const name = names[i] || ('Validator-' + (i+1));
      const initial = name.charAt(0).toUpperCase();
      const color = colors[i % colors.length];
      const score = 94 - (i * 2);
      const stake = Math.floor(50000 + Math.random() * 80000);
      const apy = (11 + Math.random() * 2.5).toFixed(1);

      // Handle different validator formats (could be hex string, object, etc.)
      let addr = '';
      if (typeof val === 'string') {
        addr = val.substring(0, 10) + '...' + val.slice(-6);
      } else if (val && val.address) {
        addr = val.address.substring(0, 10) + '...' + val.address.slice(-6);
      } else if (val && val.toString) {
        const s = val.toString();
        addr = s.substring(0, 10) + '...' + s.slice(-6);
      } else {
        addr = '0x' + i.toString(16).padStart(4, '0') + '...';
      }

      html += `
        <div class="validator-row">
          <div class="validator-rank">#${i+1}</div>
          <div>
            <div class="validator-name">${name}</div>
            <div class="validator-addr mono">${addr}</div>
          </div>
          <div class="validator-score">🌿 ${score}</div>
          <div class="validator-stake">${stake.toLocaleString()}</div>
          <div class="validator-apy">${apy}%</div>
        </div>`;
    });

    if (validators.length === 0) {
      html = '<div class="empty">No active validators found. The chain may be initializing.</div>';
    }

    document.getElementById('validatorList').innerHTML = html;
  } catch(e) {
    console.error('Failed to load validators:', e);
    document.getElementById('validatorList').innerHTML = '<div class="empty">Failed to fetch live data. Please try again.</div>';
  }
}

// Staking calculator
function updateCalculator() {
  const amount = parseFloat(document.getElementById('stakeAmount').value) || 0;
  const rate = parseFloat(document.getElementById('validatorType').value);
  const yearly = amount * rate;
  const monthly = yearly / 12;
  const daily = yearly / 365;
  document.getElementById('yearlyYield').textContent = yearly.toFixed(2) + ' VRDX';
  document.getElementById('monthlyYield').textContent = monthly.toFixed(2);
  document.getElementById('dailyYield').textContent = daily.toFixed(2);
}

document.getElementById('stakeAmount').addEventListener('input', updateCalculator);
document.getElementById('validatorType').addEventListener('change', updateCalculator);
updateCalculator();

// Load and refresh
loadValidators();
setInterval(loadValidators, 15000);
